  useEffect(() => {
    getProducts().then(setProducts);
  }, []);

  return (
    <table>
      {products.map(p => (
        <tr key={p.id}>
          <td>{p.name}</td>
          <td>{p.stock} units</td>
        </tr>
      ))}
    </table>
  );
